$ErrorActionPreference='Stop';$server=Split-Path $PSScriptRoot;. (Join-Path $server 'artifacts\ArtifactReturn.ps1');$tmp=Join-Path ([IO.Path]::GetTempPath()) ('ai5-artifact-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $tmp|Out-Null;Initialize-AI5ArtifactReturn $tmp
function A($v,$m){if(!$v){throw $m}}
try{$src=Join-Path $tmp 'source';New-Item -ItemType Directory $src|Out-Null;Set-Content -LiteralPath (Join-Path $src 'README.md') -Value 'safe artifact' -NoNewline;$zip=Join-Path $tmp 'ai5-p0.zip';Compress-Archive -Path (Join-Path $src '*') -DestinationPath $zip;$hash=(Get-FileHash $zip -Algorithm SHA256).Hash;$manifest=[pscustomobject]@{TASK_ID='task-artifact';CORRELATION_ID='corr-artifact';ARTIFACT_ID='ai5-p0';FILENAME='ai5-p0.zip';SHA256=$hash;BYTES=(Get-Item $zip).Length;MEDIA_TYPE='application/zip';SOURCE_AGENT='claude_chat';RETURN_ROUTE='RESULT_BUS'};$first=Register-AI5ReturnedArtifact $manifest $zip;A ($first.registered-and$first.zip_safety.safe) 'safe artifact registration failed';$second=Register-AI5ReturnedArtifact $manifest $zip;A (!$second.registered-and$second.duplicate) 'artifact duplicate not blocked';$bad=[pscustomobject]@{};foreach($p in $manifest.psobject.Properties){$bad|Add-Member -NotePropertyName $p.Name -NotePropertyValue $p.Value};$bad.SHA256=('0'*64);try{Register-AI5ReturnedArtifact $bad $zip|Out-Null;throw 'hash mismatch accepted'}catch{if($_.Exception.Message-eq'hash mismatch accepted'){throw}};Add-Type -AssemblyName System.IO.Compression.FileSystem;$evil=Join-Path $tmp 'evil.zip';$z=[IO.Compression.ZipFile]::Open($evil,[IO.Compression.ZipArchiveMode]::Create);$e=$z.CreateEntry('../escape.txt');$w=[IO.StreamWriter]::new($e.Open());$w.Write('x');$w.Dispose();$z.Dispose();try{Test-AI5ZipSafety $evil|Out-Null;throw 'zip traversal accepted'}catch{if($_.Exception.Message-eq'zip traversal accepted'){throw}};'ARTIFACT_RETURN_TESTS_OK'}finally{Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue}
